insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Architecture','match_the_following','hard','Consider the following pairs of temples and the dynasties under which they were built:','{"list_1": ["1. Brihadeshwara temple, Thanjavur", "2. Kailasa temple, Ellora", "3. Virupaksha temple, Pattadakal", "4. Sun temple, Modhera"], "list_2": ["Chola", "Pallava", "Chalukya of Badami", "Paramara"], "closing": "How many of the pairs given above are correctly matched?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "isCorrect": false}, {"id": "d", "body": "All four pairs", "isCorrect": false}]'::jsonb,2,0.66,'Only pairs 1 and 3 are correct. The Brihadeshwara temple at Thanjavur was built by the Chola king Rajaraja I, and the Virupaksha temple at Pattadakal was built by Queen Lokamahadevi to commemorate the victory of her husband, the Chalukya king Vikramaditya II, over the Pallavas. Pair 2 is a name trap: the monolithic Kailasa temple at Ellora was built under the Rashtrakuta king Krishna I -- it is the Kailasanatha temple at Kanchipuram that is Pallava. Pair 4 is incorrect: the Modhera Sun temple was built under Bhima I of the Chaulukya (Solanki) dynasty, not the Paramaras.','art-culture-temples-dynasties-pairs','original_pattern_matched','NCERT, An Introduction to Indian Art (Class XI) -- chapters on temple architecture.','draft'),
('upsc','History','Iconography','match_the_following','hard','Consider the following pairs of deities and the mounts (vahanas) associated with them in Hindu iconography:','{"list_1": ["1. Kartikeya", "2. Yamuna", "3. Agni", "4. Shiva"], "list_2": ["Peacock", "Makara", "Ram", "Nandi (bull)"], "closing": "How many of the pairs given above are correctly matched?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "isCorrect": true}, {"id": "d", "body": "All four pairs", "isCorrect": false}]'::jsonb,2,0.66,'Pairs 1, 3 and 4 are correct: Kartikeya (Skanda) rides a peacock, Agni a ram, and Shiva the bull Nandi. Pair 2 is a swap between the two river goddesses: the makara (a crocodile-like creature) is the mount of Ganga, while Yamuna is shown standing on a tortoise (kurma) -- the pairing that appears on temple doorways from the Gupta period onward.','art-culture-deity-vahana-pairs','original_pattern_matched','NCERT, An Introduction to Indian Art (Class XI) -- chapters on sculpture and iconography.','draft'),
('upsc','History','Painting','mcq','easy','Madhubani painting, which has received a Geographical Indication (GI) tag, is traditionally associated with which of the following States?','{}'::jsonb,'[{"id": "a", "body": "Odisha", "isCorrect": false}, {"id": "b", "body": "Maharashtra", "isCorrect": false}, {"id": "c", "body": "West Bengal", "isCorrect": false}, {"id": "d", "body": "Bihar", "isCorrect": true}]'::jsonb,2,0.66,'Madhubani (Mithila) painting belongs to the Mithila region of Bihar and received a GI tag. The other States are known for different traditions: Odisha for Pattachitra, Maharashtra for the Warli paintings of the Warli tribe, and West Bengal for Kalighat painting.','art-culture-madhubani-painting','original_pattern_matched','NCERT, An Introduction to Indian Art (Class XI) -- chapter on folk and tribal art; Geographical Indications Registry.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','medium','Consider the following statements regarding the making of the Constitution of India:','{"statements": ["The Constituent Assembly was constituted under the scheme formulated by the Cabinet Mission Plan of 1946.", "Dr. Rajendra Prasad was the Chairman of the Drafting Committee of the Constituent Assembly.", "The Constitution of India was adopted by the Constituent Assembly on 26 January 1950."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the Constituent Assembly was set up in 1946 under the Cabinet Mission Plan. Statement 2 swaps the office-holders: Dr. B. R. Ambedkar chaired the Drafting Committee, while Dr. Rajendra Prasad was the President of the Constituent Assembly. Statement 3 confuses two dates: the Constitution was adopted on 26 November 1949 and came into force on 26 January 1950.','polity-making-of-constitution','original_pattern_matched','M. Laxmikanth, Indian Polity -- chapter on the Making of the Constitution.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','medium','Consider the following statements regarding the procedure for amending the Constitution of India:','{"statements": ["An amendment affecting any of the lists in the Seventh Schedule requires ratification by the legislatures of not less than one-half of the States, in addition to a special majority in Parliament.", "An amendment of the Fundamental Rights in Part III requires ratification by the legislatures of not less than one-half of the States.", "The President is bound to give assent to a Constitution Amendment Bill duly passed under Article 368, and cannot withhold assent or return it for reconsideration."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Under the proviso to Art. 368(2), amendments to the Seventh Schedule lists (among other federal provisions) also need ratification by half the States. After the 24th Amendment (1971), the President must assent to a duly passed Constitution Amendment Bill. Statement 2 is incorrect: Fundamental Rights are amended by a special majority of Parliament alone -- they are not among the provisions listed in the proviso that require State ratification, a common assumption because of their importance.','polity-amendment-ratification-art368','original_pattern_matched','Constitution of India, Art. 368; M. Laxmikanth, Indian Polity -- chapter on Amendment of the Constitution.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','medium','Consider the following statements regarding the Schedules of the Constitution of India:','{"statements": ["The Tenth Schedule contains the provisions for disqualification of members of Parliament and State Legislatures on the ground of defection.", "The Eighth Schedule originally listed 22 languages when the Constitution came into force."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": true}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the Tenth Schedule, added by the 52nd Amendment (1985), contains the anti-defection provisions. Statement 2 is incorrect: the Eighth Schedule originally listed 14 languages; it has grown to 22 through later amendments.','polity-schedules-tenth-eighth','original_pattern_matched','M. Laxmikanth, Indian Polity -- chapter on the Schedules of the Constitution.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','medium','Consider the following statements regarding citizenship in India:','{"statements": ["The Constitution itself lays down the provisions for the acquisition and termination of citizenship after its commencement.", "Article 11 empowers Parliament to make any provision with respect to the acquisition and termination of citizenship.", "An Indian citizen who voluntarily acquires the citizenship of another country ceases to be a citizen of India."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 2 and 3 are correct: Art. 11 empowers Parliament to regulate citizenship, and under the Citizenship Act, 1955 voluntary acquisition of foreign citizenship terminates Indian citizenship. Statement 1 is incorrect: Part II of the Constitution (Arts. 5-11) deals only with who were citizens at its commencement; acquisition and loss of citizenship afterwards are governed by the Citizenship Act, 1955, enacted by Parliament.','polity-citizenship-part-ii','original_pattern_matched','Constitution of India, Arts. 5-11; Citizenship Act, 1955; M. Laxmikanth, Indian Polity -- chapter on Citizenship.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','medium','Consider the following statements regarding the Preamble to the Constitution of India:','{"statements": ["The words ''Socialist'', ''Secular'' and ''Integrity'' were added to the Preamble by the 42nd Amendment Act, 1976.", "The Preamble declares India to be a federal republic.", "In the Berubari Union case (1960), the Supreme Court held that the Preamble is a part of the Constitution."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the 42nd Amendment (1976) inserted ''Socialist'', ''Secular'' and ''Integrity''. Statement 2 is incorrect: the Preamble describes India as a Sovereign Socialist Secular Democratic Republic -- the word ''federal'' appears nowhere in the Preamble or the Constitution. Statement 3 swaps the cases: in Berubari (1960) the Court held that the Preamble is NOT a part of the Constitution; it was in Kesavananda Bharati (1973) that the Court held it is a part.','polity-preamble-amendment-cases','original_pattern_matched','M. Laxmikanth, Indian Polity -- chapter on the Preamble.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','medium','Consider the following Parts of the Constitution of India and their subject matter:','{"statements": ["Part XI deals with the relations between the Union and the States.", "Part XIV deals with services under the Union and the States.", "Part XV deals with elections."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": true}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct: Part XI (Arts. 245-263) covers Union-State relations, Part XIV (Arts. 308-323) covers services under the Union and the States, including the Public Service Commissions, and Part XV (Arts. 324-329A) covers elections.','polity-constitution-parts-xi-xiv-xv','original_pattern_matched','Constitution of India; M. Laxmikanth, Indian Polity -- chapter on the Parts of the Constitution.','draft'),
('upsc','Polity','Constitutional Framework','statement_based','medium','Consider the following statements regarding the sources from which features of the Constitution of India were borrowed:','{"statements": ["The Directive Principles of State Policy were borrowed from the Irish Constitution.", "The procedure for amendment of the Constitution was borrowed from the Constitution of South Africa.", "The Fundamental Duties were borrowed from the Constitution of the USA.", "The suspension of Fundamental Rights during an Emergency was borrowed from the Weimar Constitution of Germany."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 4 are correct: the Directive Principles came from the Irish Constitution, the amendment procedure (and the election of Rajya Sabha members) from South Africa, and the suspension of Fundamental Rights during an Emergency from the Weimar Constitution of Germany. Statement 3 is incorrect: the Fundamental Duties were drawn from the Constitution of the erstwhile USSR, not the USA.','polity-borrowed-features-sources','original_pattern_matched','M. Laxmikanth, Indian Polity -- chapter on the Salient Features of the Constitution.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements regarding the Public Accounts Committee of Parliament:','{"statements": ["The Public Accounts Committee consists of members of both the Lok Sabha and the Rajya Sabha.", "Its Chairman is appointed by the Speaker, and since 1967 the Chairman has by convention been chosen from the Opposition.", "It examines the audit reports of the Comptroller and Auditor General on the appropriation accounts and finance accounts of the Union Government."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": true}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The Public Accounts Committee has 22 members, 15 from the Lok Sabha and 7 from the Rajya Sabha. Its Chairman is appointed by the Speaker, and by convention since 1967 is from the Opposition. It examines the CAG''s audit reports on the appropriation and finance accounts of the Union Government.','polity-public-accounts-committee','original_pattern_matched','M. Laxmikanth, Indian Polity -- chapter on Parliamentary Committees.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements regarding the financial committees of Parliament:','{"statements": ["The Committee on Public Undertakings consists of members of the Lok Sabha only.", "The Estimates Committee consists of members of both the Lok Sabha and the Rajya Sabha.", "The Business Advisory Committee of the Lok Sabha is chaired by the Leader of the House."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. The Committee on Public Undertakings has members from both Houses (15 from the Lok Sabha and 7 from the Rajya Sabha). The Estimates Committee is the one drawn from the Lok Sabha alone -- all 30 of its members are from the Lok Sabha. The Business Advisory Committee of the Lok Sabha is chaired by the Speaker, not the Leader of the House.','polity-financial-committees-composition','original_pattern_matched','M. Laxmikanth, Indian Polity -- chapter on Parliamentary Committees.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements regarding the functioning of Parliament:','{"statements": ["The quorum to constitute a meeting of either House of Parliament is one-tenth of the total number of members of that House.", "The Constitution provides that the interval between two sessions of Parliament shall not exceed six months.", "The secretariat of the Lok Sabha functions under the control of the Ministry of Parliamentary Affairs."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: under Art. 100(3) the quorum is one-tenth of the total membership of the House, and under Art. 85 the gap between two sessions cannot exceed six months. Statement 3 is incorrect: Art. 98 gives each House its own secretariat, and the Lok Sabha Secretariat works under the control of the Speaker, not any ministry -- which keeps it independent of the executive.','polity-quorum-sessions-secretariat','original_pattern_matched','Constitution of India, Arts. 85, 98 and 100; M. Laxmikanth, Indian Polity -- chapter on Parliament.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements regarding the Legislative Councils in the States:','{"statements": ["Parliament may by law create or abolish the Legislative Council of a State if the Legislative Assembly of that State passes a resolution to that effect by a special majority.", "Such a law of Parliament is deemed to be an amendment of the Constitution for the purposes of Article 368.", "One-third of the members of a Legislative Council are nominated by the Governor."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: under Art. 169 Parliament can create or abolish a Legislative Council on a resolution of the State Assembly passed by a special majority. Statement 2 reverses Art. 169(3): such a law is expressly NOT deemed an amendment of the Constitution for the purposes of Art. 368, so it needs only a simple majority. Statement 3 is incorrect: only one-sixth of the members are nominated by the Governor; one-third are elected by the members of the Legislative Assembly and one-third by local bodies.','polity-legislative-council-art169','original_pattern_matched','Constitution of India, Arts. 169 and 171; M. Laxmikanth, Indian Polity -- chapter on the State Legislature.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements regarding devices of parliamentary proceedings:','{"statements": ["A short notice question can be asked with less than ten days'' notice on a matter of public importance, and is answered orally.", "The calling attention motion is an Indian innovation in parliamentary procedure, but it is not mentioned in the Rules of Procedure.", "Zero Hour is not mentioned in the Rules of Procedure."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct: a short notice question is asked with less than ten days'' notice and answered orally, and Zero Hour (in use since 1962) is an informal device with no mention in the Rules of Procedure. Statement 2 is incorrect: the calling attention motion is an Indian innovation, in use since 1954, but unlike Zero Hour it is provided for in the Rules of Procedure.','polity-parliamentary-devices-zero-hour','original_pattern_matched','M. Laxmikanth, Indian Polity -- chapter on Parliament (devices of parliamentary proceedings).','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements regarding a joint sitting of the two Houses of Parliament:','{"statements": ["A joint sitting of the two Houses is presided over by the Chairman of the Rajya Sabha.", "Since 1950, the provision for a joint sitting has been invoked more than five times."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": true}]'::jsonb,2,0.66,'Neither statement is correct. Under Art. 118(4) a joint sitting is presided over by the Speaker of the Lok Sabha (in the Speaker''s absence, the Deputy Speaker, and then the Deputy Chairman of the Rajya Sabha) -- not the Chairman of the Rajya Sabha. The provision has been invoked only three times: for the Dowry Prohibition Bill (1961), the Banking Service Commission (Repeal) Bill (1978) and the Prevention of Terrorism Bill (2002).','polity-joint-sitting-art108','original_pattern_matched','Constitution of India, Arts. 108 and 118; M. Laxmikanth, Indian Polity -- chapter on Parliament.','draft'),
('upsc','Polity','Parliament & State Legislature','statement_based','medium','Consider the following statements regarding the presiding officers of the Lok Sabha:','{"statements": ["The Speaker pro tem is appointed by the President.", "The office of the Leader of the Opposition in the Lok Sabha is provided for in the Constitution.", "The Deputy Speaker may resign from office by writing addressed to the Speaker.", "The decision of the Speaker on whether a Bill is a Money Bill is final."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 3 and 4 are correct: the President appoints the Speaker pro tem; under Art. 94 the Deputy Speaker resigns by writing to the Speaker; and under Art. 110(3) the Speaker''s decision on whether a Bill is a Money Bill is final. Statement 2 is incorrect: the Leader of the Opposition has statutory, not constitutional, recognition, under the Salary and Allowances of Leaders of Opposition in Parliament Act, 1977.','polity-presiding-officers-lok-sabha','original_pattern_matched','Constitution of India, Arts. 94 and 110; M. Laxmikanth, Indian Polity -- chapter on Parliament.','draft')
